function safeBox(box){if(!box||!['x','y','w','h'].every(k=>Number.isFinite(box[k]))||box.w<=0||box.h<=0)return null;const x=Math.max(0,box.x),y=Math.max(0,box.y),right=Math.min(1,box.x+box.w),bottom=Math.min(1,box.y+box.h);return right>x&&bottom>y?{x,y,w:right-x,h:bottom-y}:null}
export function spatialFrameMarks(frame){const marks=[];for(const r of frame.rectangles||[]){const box=safeBox({x:r.x-r.w/2,y:r.y-r.h/2,w:r.w,h:r.h});if(box)marks.push({shape:'rectangle',label:'单帧矩形边界',box})}for(const c of frame.circles||[]){const box=safeBox({x:c.x-c.r,y:c.y-c.ry,w:c.r*2,h:c.ry*2});if(box)marks.push({shape:'ellipse',label:'单帧圆形边界',box})}const person=safeBox(frame.person?.box);if(person)marks.push({shape:'person',label:'新计算的人物前景范围',box:person});return marks}
export function textFrameMarks(frame){return(frame.lines||[]).flatMap(line=>{const box=safeBox(line.box);return box?[{shape:'text',label:line.text||'文字候选',box}]:[]})}
export function filterReviewFrames(frames,filter='all'){return frames.filter(f=>filter==='people'?!!f.person:filter==='geometry'?!!(f.circles?.length||f.rectangles?.length):true)}
export function pageReviewFrames(frames,page=0,size=8){const pages=Math.max(1,Math.ceil(frames.length/size)),current=Math.min(pages-1,Math.max(0,Math.trunc(Number(page))||0));return{frames:frames.slice(current*size,(current+1)*size),page:current,pages,total:frames.length,start:current*size}}
export function validFrameTime(value,duration){return Number.isFinite(value)&&Number.isFinite(duration)&&duration>0&&value>=0&&value<=duration?Math.min(value,Math.max(0,duration-.001)):null}
